// MLE 常见原因：
// int dp[10000][10000];  // 约 400MB，超限
// 解决：用滚动数组
// int dp[2][10000];  // 约 80KB

// OLE 常见原因：
// while (true) cout << 1;  // 无限输出
// 调试用的 cout 没注释掉

// WA 排查清单：
// □ 重新读题，确认理解正确
// □ 手推样例
// □ 检查数据类型（long long？）
// □ 检查边界（n=1？n=0？）
// □ 检查输出格式
// □ 多组数据变量重置

for (int i = 0; i < n; i++) {
    assert(i >= 0 && i < n);
    // 使用 a[i]
    if (i + 1 < n) {
        // 使用 a[i+1] 安全
    }
}

int cnt = 0;
while (condition) {
    cnt++;
    if (cnt > 1000000) {
        cerr << "可能死循环！当前变量: " << /* 关键变量 */ << endl;
        break;
    }
    // 循环体
}

// 可能溢出：
int deepRecurse(int n) {
    if (n == 0) return 0;
    return deepRecurse(n - 1) + 1;  // n 很大时溢出
}

// 安全：改用循环
int iterate(int n) {
    int result = 0;
    for (int i = 0; i < n; i++) result++;
    return result;
}

